parts.output:
{
  description = "Kasiro's NixOS configuration";

  inputs = {
    # Stable — основной
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-25.05";

    # Unstable — для отдельных пакетов
    nixpkgs-unstable.url = "github:NixOS/nixpkgs/nixos-unstable";

    # Home Manager синхронизированный со stable
    home-manager = {
      url = "github:nix-community/home-manager/release-25.05";
      inputs.nixpkgs.follows = "nixpkgs";
    };
  };

  outputs = { self, nixpkgs, nixpkgs-unstable, home-manager, ... }@inputs:
    let
      system = "x86_64-linux";
      pkgs-unstable = nixpkgs-unstable.legacyPackages.${system};
    in {
      nixosConfigurations.nixos = nixpkgs.lib.nixosSystem {
        inherit system;
        modules = [
          ./configuration.nix
          home-manager.nixosModules.home-manager
          {
            # Overlay: stable по умолчанию, unstable fallback
            nixpkgs.overlays = [
              (final: prev: {
                opencode = prev.opencode or pkgs-unstable.opencode;
              })
            ];
            home-manager.extraSpecialArgs = { inherit inputs pkgs-unstable; };
            home-manager.users.kasiro = import ./home/kasiro.nix;
            home-manager.users.whitepeach = import ./home/whitepeach.nix;
          }
        ];
      };
    };
}

